def mensalistas_join_this_month(apps, schema_editor):
    Player = apps.get_model("accounts", "Player")
    MonthlyEnrollment = apps.get_model("accounts", "MonthlyEnrollment")
    GameDay = apps.get_model("games", "GameDay")
    month = core.clock.now().date().replace(day=1)
    months = {day.replace(day=1) for day in GameDay.objects.filter(date__lt=month).values_list("date", flat=True)}
    months.add(month)
    mensalistas = Player.objects.filter(player_type="mensalista")
    MonthlyEnrollment.objects.bulk_create(
        [
            MonthlyEnrollment(
                player_id=pk,
                month=covered_month,
                enrolled_at=datetime.combine(covered_month, time.min, tzinfo=core.clock.SAO_PAULO),
            )
            for pk in mensalistas.values_list("pk", flat=True)
            for covered_month in sorted(months)
        ],
        ignore_conflicts=True,
    )
    mensalistas.update(player_type="avulso")


def enrolled_become_mensalistas(apps, schema_editor):
    Player = apps.get_model("accounts", "Player")
    MonthlyEnrollment = apps.get_model("accounts", "MonthlyEnrollment")
    month = core.clock.now().date().replace(day=1)
    enrolled = MonthlyEnrollment.objects.filter(month=month).values("player_id")
    Player.objects.filter(pk__in=enrolled).update(player_type="mensalista")


